const DBS = ["YOUR_NOTION_DB_MAIN", "YOUR_NOTION_DB_CLOUD", "YOUR_NOTION_DB_SECURITY"];
const TOKEN = "YOUR_NOTION_TOKEN";
const body = {"filter": {"and": [{"property": "Status", "select": {"equals": "Applying"}}, {"property": "Drive Folder", "url": {"is_empty": true}}, {"property": "Score", "number": {"is_not_empty": true}}]}};
let all = [];
for (const db of DBS) {
  const resp = await this.helpers.httpRequest({
    method: 'POST',
    url: `https://api.notion.com/v1/databases/${db}/query`,
    headers: { 'Authorization': `Bearer ${TOKEN}`, 'Notion-Version': '2022-06-28', 'Content-Type': 'application/json' },
    body, json: true
  });
  if (resp && Array.isArray(resp.results)) all = all.concat(resp.results);
}
return [{ json: { results: all } }];

const results = ($json.results || []);
if (!results.length) return [];  // nothing to process — workflow stops cleanly
return [{ json: results[0] }];   // process one at a time; next poll picks up the rest

const page = $json;
const props = page.properties || {};

const title    = (props['Job Title']?.title?.[0]?.text?.content || 'Unknown Title').trim();
const company  = (props['Company']?.rich_text?.[0]?.text?.content || 'Unknown Company').trim();
const roleType = props['Role Type']?.select?.name || 'Other';
const tags     = (props['Tags']?.multi_select || []).map(t => t.name);
const applyUrl = props['Apply URL']?.url || '';
const score    = props['Score']?.number || 0;
const fitSummary = props['Fit Summary']?.rich_text?.[0]?.text?.content || '';

function slugify(s, max) {
  return s.replace(/[^\w\s-]/g, '').replace(/\s+/g, ' ').trim().substring(0, max || 60);
}

const docDate     = new Date().toISOString().split('T')[0];
const folderName  = slugify(`${company} - ${title}`, 80);
const resumeTitle = `Resume - ${slugify(title, 45)} - ${company.substring(0, 25)} ${docDate}`;
const clTitle     = `Cover Letter - ${slugify(title, 40)} - ${company.substring(0, 25)} ${docDate}`;

return [{ json: {
  page_id:      page.id,
  title, company, role_type: roleType, tags, apply_url: applyUrl, score, fit_summary: fitSummary,
  folder_name: folderName, resume_title: resumeTitle, cl_title: clTitle,
}}];

const blocks = $json.results || [];
const pageInfo = $('Extract Page Info').first().json;

let inDesc = false;
const parts = [];

for (const block of blocks) {
  if (block.type === 'heading_2') {
    const text = block.heading_2?.rich_text?.[0]?.text?.content || '';
    if (text.includes('Full Job Description')) { inDesc = true; continue; }
    if (inDesc) break;
  }
  if (block.type === 'divider' && inDesc) break;
  if (inDesc && block.type === 'paragraph') {
    const t = block.paragraph?.rich_text?.[0]?.text?.content || '';
    if (t) parts.push(t);
  }
}

const description = parts.join('\n').substring(0, 5000);
return [{ json: { ...pageInfo, description } }];

const j = $json;
const resumeText = $json.resumeText || 'ERROR: resumeText missing from Resume Content node';

const tagsList = (j.tags || []).join(', ') || 'Not specified';
const desc     = (j.description || 'No description provided').substring(0, 3500);

// ── Cached prefix ─────────────────────────────────────────────────────────
// Byte-identical on every run, so it can be cached. The only interpolation is
// resumeText, which is a constant from the Resume Content node. NOTHING
// job-specific may go in here - a single changed byte invalidates the entry
// and every call pays the write premium instead of the read discount.
const systemText = `You are a professional resume writer helping a senior network/infrastructure engineer tailor application materials for a specific job opening.

CANDIDATE BASE RESUME — USE THIS AS THE AUTHORITATIVE SOURCE:
${resumeText}

INSTRUCTIONS:
Tailor the candidate's resume for this specific role. Keep all factual claims accurate — do not invent experience or credentials. Reorder emphasis within roles to highlight skills this job values, but PRESERVE ALL CONTENT. Preserve all specific metrics (1,200 routers, 100 servers, 1,600 rules, 350 locations, etc.).

INCLUDE A PROJECTS SECTION: Populate "projects" using the candidate's platform/automation projects from the base resume (e.g. NOLA — AI Infrastructure Assistant, Job Scout, Multi-Site Personal Infrastructure). Order by relevance to this role, keep 1–2 bullets each, and preserve specific tools and metrics.

CRITICAL — ALL 6 WORK HISTORY ENTRIES ARE REQUIRED in the experience array, in this exact order:
  1. [Current Employer] ([Year]–Present) — include 4–5 bullets, emphasize most relevant work
  2. [Previous Employer] ([Year]–[Year]) — include 4–5 bullets
  3. [Previous Employer] ([Year]–[Year]) — include 3–4 bullets
  4. [Earlier Employer] ([Year]–[Year]) — include 2–3 bullets
DO NOT drop, combine, skip, or merge any of these 6 entries. Every one must appear.

Return ONLY valid JSON with no markdown fences, no extra text:

{
  "resume_sections": {
    "summary": "2–3 sentence professional summary written specifically for this role at this company",
    "core_competencies": ["12 competency phrases most relevant to this specific job — pick from the candidate's real skills, ordered by relevance to this role"],
    "projects": [
      {
        "name": "project name from the base resume",
        "tech": "short tech stack, e.g. n8n · Claude · Prometheus",
        "bullets": ["1–2 concise bullets — preserve specific tools and metrics"]
      }
    ],
    "experience": [
      {
        "company": "exact company name",
        "title": "exact title held",
        "dates": "date range",
        "location": "city, state or Remote",
        "bullets": ["achievement bullets rewritten to lead with skills this job values most — preserve all specific metrics"]
      }
    ],
    "technical_skills": "Technical skills paragraph with technologies most relevant to this role listed first — preserve all skills from the base resume, reordered by relevance",
    "education": "Bachelor of Applied Science, Information Security Systems | Your University\nBachelor of Applied Science, Electronics/Communications Engineering Technology | Your University\nAssociate of Applied Science, Computer/Electronics Engineering Technology | Your University\nCertifications: CCNA (2011, 97%) | BICSI Cable Installation"
  },
  "cover_letter": "Full 3–4 paragraph cover letter.\n\nParagraph 1 (hook): Open with something specific about the target company named in the job details and why this role is a strong fit — reference the company's industry, mission, or something distinctive.\n\nParagraph 2 (proof): Highlight 2–3 most relevant experiences with specific metrics. Connect directly to requirements in the job description.\n\nParagraph 3 (value): Explain the specific value the candidate brings — what problems they have solved that map directly to what this company needs.\n\nParagraph 4 (close): Professional closing with enthusiasm and call to action."
}`;

// ── Volatile suffix ───────────────────────────────────────────────────────
// Changes per job, so it sits after the cache breakpoint as the user turn.
const userText = `TARGET POSITION:
Title: ${j.title}
Company: ${j.company}
Role Type: ${j.role_type}
Key Skills Needed: ${tagsList}

JOB DESCRIPTION:
${desc}

`;

return [{ json: { ...j, systemText, userText } }];

const resp = $input.first().json;
const j    = $('Build Prompt').first().json;

// DEBUG: expose what resp actually contains
const respKeys   = Object.keys(resp);
const hasContent = Array.isArray(resp.content);
const hasChoices = Array.isArray(resp.choices);
const anthropicRaw = hasContent ? (resp.content[0] || {}).text || '' : '';
const openaiRaw    = hasChoices ? ((resp.choices[0] || {}).message || {}).content || '' : '';
const raw = anthropicRaw || openaiRaw || '';

let result = {};
try {
  const BT = String.fromCharCode(96);
const BT3 = BT + BT + BT;
const cleaned = raw
  .replace(new RegExp(BT3 + 'json\s*', 'g'), '')
  .replace(new RegExp(BT3 + '\s*', 'g'), '')
  .trim();
  result = JSON.parse(cleaned);
} catch(e) {
  result = { resume_sections: null, cover_letter: raw || 'Parse failed.' };
}

const s = result.resume_sections;

// DEBUG: if still failing, surface detail in the resume doc
const debugInfo = [
  'resp keys: ' + respKeys.join(', '),
  'hasContent: ' + hasContent,
  'hasChoices: ' + hasChoices,
  'raw length: ' + raw.length,
  'raw start:  ' + raw.substring(0,120),
].join('\n');

const DARK_BLUE = { color: { rgbColor: { red: 0.110, green: 0.239, blue: 0.376 } } };
const MED_GRAY  = { color: { rgbColor: { red: 0.40,  green: 0.40,  blue: 0.40  } } };

let resumeText    = '';
let docPos        = 1;
const fmtRequests = [];

function addPart(text, textStyle, align) {
  if (!text) return;
  const start = docPos;
  resumeText += text;
  docPos += text.length;
  const end = docPos;
  if (textStyle) {
    let styleEnd = end;
    for (let i = text.length - 1; i >= 0 && text[i] === '\n'; i--) styleEnd--;
    if (styleEnd > start) {
      const ts = {}, fields = [];
      if (textStyle.bold      !== undefined) { ts.bold   = textStyle.bold;   fields.push('bold'); }
      if (textStyle.italic    !== undefined) { ts.italic = textStyle.italic; fields.push('italic'); }
      if (textStyle.fontSize  !== undefined) { ts.fontSize = { magnitude: textStyle.fontSize, unit: 'PT' }; fields.push('fontSize'); }
      if (textStyle.foregroundColor) { ts.foregroundColor = textStyle.foregroundColor; fields.push('foregroundColor'); }
      if (fields.length) fmtRequests.push({ updateTextStyle: { range: { startIndex: start, endIndex: styleEnd }, textStyle: ts, fields: fields.join(',') }});
    }
  }
  if (align) fmtRequests.push({ updateParagraphStyle: { range: { startIndex: start, endIndex: end }, paragraphStyle: { alignment: align }, fields: 'alignment' }});
}

function sectionHeader(title) {
  addPart(title + '\n', { bold: true, fontSize: 11, foregroundColor: DARK_BLUE });
}

if (s) {
  addPart('YOUR NAME\n', { bold: true, fontSize: 18 }, 'CENTER');
  addPart('Your City, WA  •  555.555.0100  •  you@example.com  •  yourwebsite.example\n', { fontSize: 10 }, 'CENTER');
  addPart('\n');
  addPart('Tailored for: ' + j.title + ' — ' + j.company + '\n', { italic: true, fontSize: 9, foregroundColor: MED_GRAY }, 'CENTER');
  addPart('\n');
  sectionHeader('PROFESSIONAL SUMMARY');
  addPart((s.summary || '') + '\n', { fontSize: 10 });
  addPart('\n');
  sectionHeader('CORE COMPETENCIES');
  addPart((s.core_competencies || []).join('  •  ') + '\n', { fontSize: 10 });
  addPart('\n');
  if (s.projects && s.projects.length) {
    sectionHeader('TECHNICAL PROJECTS');
    for (const proj of s.projects) {
      const tech = proj.tech ? '  (' + proj.tech + ')' : '';
      addPart((proj.name || '') + tech + '\n', { bold: true, fontSize: 10 });
      for (const bullet of (proj.bullets || [])) {
        addPart('    •  ' + bullet + '\n', { fontSize: 10 });
      }
    }
    addPart('\n');
  }
  sectionHeader('PROFESSIONAL EXPERIENCE');
  for (const exp of (s.experience || [])) {
    addPart((exp.company || '').toUpperCase() + '\n', { bold: true, fontSize: 11 });
    const loc = exp.location ? '  —  ' + exp.location : '';
    addPart((exp.title || '') + loc + '  |  ' + (exp.dates || '') + '\n', { italic: true, fontSize: 10 });
    for (const bullet of (exp.bullets || [])) {
      addPart('    •  ' + bullet + '\n', { fontSize: 10 });
    }
    addPart('\n');
  }
  sectionHeader('TECHNICAL SKILLS');
  addPart((s.technical_skills || '') + '\n', { fontSize: 10 });
  addPart('\n');
  sectionHeader('EDUCATION & CERTIFICATIONS');
  addPart((s.education || '') + '\n', { fontSize: 10 });
} else {
  addPart('=== RESUME GENERATION DEBUG ===\n', { bold: true, fontSize: 12 });
  addPart(debugInfo + '\n', { fontSize: 10 });
  addPart('\n=== RAW CLAUDE OUTPUT (first 2000 chars) ===\n', { bold: true, fontSize: 10 });
  addPart((raw || '(empty)').substring(0, 2000) + '\n', { fontSize: 9 });
}

const coverLetterText = [
  j.company, 'Re: ' + j.title,
  'Date: ' + new Date().toLocaleDateString('en-US', { year:'numeric', month:'long', day:'numeric' }),
  '', result.cover_letter || 'Cover letter generation failed.', '',
  'Sincerely,', 'Your Name',
  'you@example.com  |  555.555.0100  |  yourwebsite.example',
].join('\n');

const resumeBatchBody = JSON.stringify({ requests: [{ insertText: { location: { index: 1 }, text: resumeText } }, ...fmtRequests] });
const clBatchBody = JSON.stringify({ requests: [{ insertText: { location: { index: 1 }, text: coverLetterText } }] });

return [{ json: { ...j, resume_text: resumeText, cover_letter_text: coverLetterText,
  resume_batch_body: resumeBatchBody, cl_batch_body: clBatchBody } }];

const d       = $('Parse Docs').first().json;
const resume  = $('Create Resume Doc').first().json;
const cl      = $('Create Cover Letter Doc').first().json;
const folder  = $('Create App Folder').first().json;

const folderId  = folder.id;
const folderUrl = 'https://drive.google.com/drive/folders/' + folderId;
const resumeUrl = 'https://docs.google.com/document/d/' + resume.documentId + '/edit';
const clUrl     = 'https://docs.google.com/document/d/' + cl.documentId + '/edit';

const discordMsg = [
  '\uD83D\uDCC4 **Application docs ready!**',
  `**${d.title}** @ ${d.company}`,
  `Score: ${d.score}  \u2022  ${d.role_type}`,
  '',
  `\uD83D\uDCC1 [Application Folder](${folderUrl})`,
  `\uD83D\uDCDD [Tailored Resume](${resumeUrl})`,
  `\u2709\uFE0F [Cover Letter](${clUrl})`,
  '',
  `Apply: ${d.apply_url || '(see Notion page)'}`,
].join('\n');

return [{ json: {
  page_id:      d.page_id,
  discord_msg:  discordMsg,
  notion_patch: JSON.stringify({
    properties: {
      'Status':       { select: { name: 'Docs Ready' } },
      'Drive Folder': { url: folderUrl },
    }
  }),
}}];

// Prevents double-processing if the 10-min poll fires while a job is mid-run.
// Uses per-workflow static data (free, built-in, survives restarts).
const state = $getWorkflowStaticData('global');
const pageId = $json.id;
const inProgress = state.processing || {};
const staleAfterMs = 30 * 60 * 1000; // 30 min safety release

// Clear stale locks first
const now = Date.now();
for (const [pid, ts] of Object.entries(inProgress)) {
  if (now - ts > staleAfterMs) delete inProgress[pid];
}

if (inProgress[pageId]) {
  return []; // already being processed — skip
}

inProgress[pageId] = now;
state.processing = inProgress;

return [{ json: $json }];

// Release the processing lock for this page so future polls can re-process
// if the job ever gets reset back to 'Applying' status.
const state = $getWorkflowStaticData('global');
const pageId = $('Guard Duplicate').first().json.id;
const inProgress = state.processing || {};
delete inProgress[pageId];
state.processing = inProgress;
return [{ json: { cleared: pageId } }];

// Emit this call's token spend to InfluxDB. Runs as a side branch off the
// Claude node so the pipeline is never gated on a cost write.
// Pricing mirrors scripts/log-ai-cost.sh in the NOLA repo - USD per 1M tokens,
// verified 2026-08-26.
const resp = $input.first().json;
const u = resp.usage || {};

const model        = resp.model || 'unknown';
const inputTokens  = u.input_tokens  || 0;
const outputTokens = u.output_tokens || 0;
// Present only when the request used prompt caching.
const cacheRead    = u.cache_read_input_tokens     || 0;
const cacheWrite   = u.cache_creation_input_tokens || 0;

let inCpm, outCpm;
if      (model.includes('haiku'))    { inCpm =  1.00; outCpm =  5.00; }
else if (model.includes('sonnet-5')) { inCpm =  2.00; outCpm = 10.00; }
else if (model.includes('sonnet'))   { inCpm =  3.00; outCpm = 15.00; }
else if (model.includes('opus'))     { inCpm =  5.00; outCpm = 25.00; }
else if (model.includes('fable'))    { inCpm = 10.00; outCpm = 50.00; }
else                                 { inCpm =  1.00; outCpm =  5.00; }

// tokens * (USD per 1M) lands directly in micro-dollars, which keeps the field
// an integer in InfluxDB. Cache reads bill at 0.1x input. This workflow caches
// with ttl=1h, whose write premium is 2x - NOT the 1.25x of the 5m default.
// The response does not report which TTL was used, so it is pinned here.
const micro = Math.round(
  inputTokens  * inCpm  +
  outputTokens * outCpm +
  cacheRead    * inCpm * 0.10 +
  cacheWrite   * inCpm * 2.00
);

const esc = s => String(s).replace(/[ ,=]/g, '\\$&');

const line =
  `ai_cost,workflow=${esc('job-application-doc-generator')},model=${esc(model)} ` +
  `input_tokens=${inputTokens}i,output_tokens=${outputTokens}i,` +
  `cache_read_tokens=${cacheRead}i,cache_write_tokens=${cacheWrite}i,` +
  `cost_microdollars=${micro}i ${Date.now() * 1000000}`;

return [{ json: { line, model, micro } }];

// Fan out one item per Notion board so a single credentialed HTTP node can
// query all three. A Code node cannot use n8n credentials - that is why the
// legacy "Query Applying Jobs" node hardcodes a Notion token. This branch
// does not, and must not.
//
// Deliberately NOT a Merge: n8n Merge v3 silently ignores input ports past
// idx 1, which has cost this pipeline a 10-day silent outage before.
const DBS = [
  { db_id: 'YOUR_NOTION_DB_MAIN', board: 'Jobs' },
  { db_id: 'YOUR_NOTION_DB_CLOUD', board: 'Cloud Networking' },
  { db_id: 'YOUR_NOTION_DB_SECURITY', board: 'Network Security' },
];

return DBS.map(d => ({ json: d }));

// The three board queries land here as three separate items. Flatten them,
// then take a single page per poll - the same one-at-a-time discipline the
// docs branch uses. It keeps Notion under its ~3 req/s limit and keeps every
// Claude call scoped to one job.
const pages = [];
for (const item of $input.all()) {
  const r = item.json.results;
  if (Array.isArray(r)) pages.push(...r);
}
if (!pages.length) return [];   // nothing queued - branch stops cleanly

// Same static-data lock the docs branch uses, under its own key so the two
// can never collide.
const state = $getWorkflowStaticData('global');
const now = Date.now();
const STALE_MS = 30 * 60 * 1000;   // safety release if a run dies mid-flight

const locks = state.scoring || {};
for (const [pid, ts] of Object.entries(locks)) {
  if (now - ts > STALE_MS) delete locks[pid];
}

const page = pages.find(p => !locks[p.id]);
if (!page) { state.scoring = locks; return []; }

locks[page.id] = now;
state.scoring = locks;

return [{ json: page }];

// Decide what text we will score against, and pull whatever the row already
// has so Parse Score knows which cells are blank and safe to fill.
const page   = $('Pick One Page').first().json;
const props  = page.properties || {};
const blocks = $json.results || [];

const rt  = p => (p && p.rich_text && p.rich_text[0] && p.rich_text[0].text
                    ? p.rich_text[0].text.content : '').trim();
const sel = p => (p && p.select ? p.select.name : '') || '';

const title    = (props['Job Title'] && props['Job Title'].title
                  && props['Job Title'].title[0] && props['Job Title'].title[0].text
                  ? props['Job Title'].title[0].text.content : '').trim();
const company  = rt(props['Company']);
const location = rt(props['Location']);
const applyUrl = (props['Apply URL'] && props['Apply URL'].url) || '';

// Any prose already sitting on the page. If he pasted the job description in
// by hand, use that and skip the scrape entirely - Jina returns navigation
// junk for Workday/LinkedIn postings behind a login, so a hand-paste is the
// reliable escape hatch when scraping fails.
const parts = [];
for (const b of blocks) {
  const rich = b[b.type] && b[b.type].rich_text;
  if (Array.isArray(rich) && rich.length) {
    const s = rich.map(x => x.plain_text || (x.text && x.text.content) || '').join('');
    if (s.trim()) parts.push(s.trim());
  }
}
const pasted = parts.join('\n').trim();

const MIN_USABLE = 400;              // shorter than this is a note, not a JD
const usePasted  = pasted.length >= MIN_USABLE;

return [{ json: {
  page_id:  page.id,
  db_id:    (page.parent && page.parent.database_id) || '',
  page_url: page.url || '',
  // Which cells are already populated - Parse Score fills only the blanks so
  // anything typed by hand wins over anything Claude infers.
  title, company, location, apply_url: applyUrl,
  // Which status triggered this. "Applying" means he wants documents, so
  // Parse Score must hand the row back as "Applying", not "New", or the docs
  // branch would never see it.
  origin_status:   sel(props['Status']),
  has_source:      !!sel(props['Source']),
  has_date_found:  !!(props['Date Found'] && props['Date Found'].date),
  pasted_description: usePasted ? pasted.substring(0, 6000) : '',
  needs_fetch: !usePasted && !!applyUrl,
}}];

// Single-job scoring prompt. The rubric below is a verbatim port of the ATS
// Scout's format_prompt.js so a hand-added job lands on the SAME 0-100 scale
// as a scouted one - that comparability is the whole point of the column.
// If you change the rubric in one place, change it in the other.
const d = $('Resolve Description').first().json;

// On the fetch path Jina feeds this node; on the pasted path Resolve
// Description feeds it directly. Take whichever actually carries text.
let scraped = '';
if (!d.pasted_description) {
  const raw = $json.data !== undefined ? $json.data : $json.body;
  if (typeof raw === 'string') scraped = raw;
}

let content = d.pasted_description || scraped || '';

// Same boilerplate trim the Apply From URL path uses.
const simIdx = content.search(/#{2,3}\s*Similar jobs/i);
if (simIdx > 0) content = content.substring(0, simIdx);
const h1idx = content.search(/\n#\s+/);
if (h1idx > 200) content = content.substring(h1idx);
content = content.substring(0, 6000).trim();

const haveDesc = content.length >= 200;
const description = haveDesc
  ? content
  : 'No job description could be retrieved for this posting.';

// ── Title tier + skill overlap (2026-10-04) ─────────────────────────────
// Same block as ats_scout_src/normalize_ats.js and the Daily Scout's Normalize
// node - change all three together, or a hand-added job and a scouted one
// stop landing on the same scale.
// Whole word, plural allowed: 'firewall' counts 'firewalls', 'java' skips JavaScript.
const kwHit = (txt, k) => new RegExp('(^|[^a-z0-9])' + k.replace(/[.*+?^${}()|[\]\\/]/g, '\\$&') + '(e?s)?([^a-z0-9]|$)').test(txt);
const PRIMARY_T = /\bnetwork\b.*\b(engineer|architect|administrator|analyst|specialist)\b|\bfirewall engineer|\bwireless engineer|\bnoc engineer/;
const SECONDARY_T = /\binfrastructure\b.*\b(engineer|architect|administrator)\b|\binfrastructure operations|\bsystems? (engineer|administrator)|\bsysadmin|\bvirtualization|\bvmware|\bserver (engineer|administrator)|\bdata center engineer|\bcloud engineer|\bhybrid cloud/;
const SKILLS = {
  network:  ['bgp','ospf','mpls','dmvpn','vlan','qos','spanning tree','stp','multicast',
             'cisco','nexus','nx-os','ios-xe','juniper','junos','mist','aruba','meraki',
             'sd-wan','sdwan','routing','switching','wireless','wlc','dns','dhcp','ipam',
             'vpn','wan','lan','load balanc','f5'],
  security: ['palo alto','fortinet','fortigate','checkpoint','check point','asa',
             'firewall','intrusion prevention','ips','radius','zero trust','cloudflare',
             'pci','802.1x','nac','ise','segmentation'],
  systems:  ['vmware','vsphere','esxi','proxmox','hyper-v','virtualization','linux',
             'red hat','rhel','centos','windows server','active directory','docker',
             'kubernetes','k8s','container','backup','disaster recovery','azure','aws'],
  observability: ['solarwinds','orion','prometheus','grafana','splunk','elastic','syslog',
             'snmp','netflow','monitoring','loki','observability'],
  automation: ['ansible','python','n8n','automation','scripting','api'],
};
const DEVOPS_SIG = ['ci/cd','cicd','jenkins','github actions','gitlab ci','argocd','argo cd',
  'helm','slo','error budget','sre','site reliability','devops','microservices','golang',
  'rust','java','spring boot','software development','release engineering','build pipeline'];
const __t = String(d.title || '').toLowerCase();
const title_tier = !d.title ? 'unknown (no title on the row)'
  : PRIMARY_T.test(__t) ? 'primary' : SECONDARY_T.test(__t) ? 'secondary' : 'other';
const __txt = (String(d.title || '') + ' ' + (haveDesc ? description.substring(0, 3000) : '')).toLowerCase();
const __by = {};
let __hits = 0;
for (const [cl, kws] of Object.entries(SKILLS)) {
  __by[cl] = kws.filter(k => kwHit(__txt, k)).length;
